/* playback/core.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {
   // token of fade-in currently animating

  /* ---------- helpers ---------- */

  function assetUrl(relative) {
    const tail = String(relative).split("/").filter(Boolean)
      .map((part) => encodeURIComponent(part))
      .join("/");
    if (P.SITE_ROOT) return new URL(tail, P.SITE_ROOT).href;
    return `../../${tail}`;
  }

  // Baked effects live in blob: URLs. They are already absolute and must not
  // be passed through assetUrl(), which would URL-encode the blob prefix.
  function sourceUrl(track) {
    const value = P.sourceTrackPath(track);
    if (!value) return "";
    return /^(?:[a-z]+:)?\/\//i.test(value) || value.startsWith("blob:") || value.startsWith("data:")
      ? value
      : P.assetUrl(value);
  }

  function playableUrl(track) {
    const value = P.resolveTrackPath(track);
    if (!value) return "";
    return /^(?:[a-z]+:)?\/\//i.test(value) || value.startsWith("blob:") || value.startsWith("data:")
      ? value
      : P.assetUrl(value);
  }

  function basePrefix() {
    const link = [...document.querySelectorAll('link[rel="stylesheet"]')]
      .find((el) => /styles\/base\.css/.test(el.getAttribute("href") || ""));
    const match = (link?.getAttribute("href") || "").match(/^(.*?)styles\/base\.css/);
    return match ? match[1] : "./";
  }

  function cssVar(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  function formatTime(seconds) {
    if (!Number.isFinite(seconds) || seconds < 0) return "0:00";
    const total = Math.floor(seconds);
    return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
  }

  /* ---------- audio formats ---------- */

  function trackFormats(track) {
    if (!track) return {};
    if (track.formats && typeof track.formats === "object") return track.formats;
    const match = String(track.path || "").match(/\.([^.]+)$/);
    return match ? { [match[1].toLowerCase()]: track.path } : {};
  }

  // The selected format wins, but a missing file never breaks playback: we
  // fall back to the track's canonical path, then to opus, then to whatever
  // version is actually present in the catalog.
  function sourceTrackPath(track) {
    const formats = P.trackFormats(track);
    if (P.state.format && formats[P.state.format]) return formats[P.state.format];
    return track?.path || formats.opus || Object.values(formats)[0] || "";
  }

  // Playback uses the baked version only when its settings signature still
  // matches. While a new render is in flight the original file keeps playing,
  // so changing a slider never freezes or corrupts the current track.
  function renderKey(source, key) {
    return `${source}\u0000${key}`;
  }

  function renderedEntry(track) {
    const source = P.sourceUrl(track);
    if (!source || !P.anyFxEnabled()) return null;
    const entry = P.renderedTrackCache.get(P.renderKey(source, P.fxSettingsKey()));
    return entry?.source === source ? entry : null;
  }

  function isTrackRendered(track) {
    return !!P.renderedEntry(track);
  }

  function resolveTrackPath(track) {
    const source = P.sourceTrackPath(track);
    if (!source || !P.anyFxEnabled()) return source;
    return P.renderedEntry(track)?.url || source;
  }

  function setFormat(name) {
    if (P.programLocked || !P.FORMATS.includes(name) || name === P.state.format) return;
    const wasPlaying = !P.audio.paused;
    const time = P.audio.currentTime || 0;
    P.state.format = name;
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
    if (!P.state.current) return;

    const formats = P.trackFormats(P.state.current);
    if (!formats[name]) return;
    P.loadCurrent({ autoplay: wasPlaying, startTime: time });
  }

  function notify(type) {
    const detail = P.getState();
    P.listeners.forEach((handler, event) => {
      if (event === type || event === "state") {
        try { handler(detail); } catch {}
      }
    });
    window.dispatchEvent(new CustomEvent("zqwy:playerstate", { detail }));
  }

  function getState() {
    return {
      current: P.state.current ? { ...P.state.current } : null,
      context: P.state.context ? { ...P.state.context } : null,
      playing: !!(P.state.current && !P.audio.paused && !P.audio.ended),
      time: P.audio.currentTime || 0,
      duration: Number.isFinite(P.audio.duration) ? P.audio.duration : 0,
      volume: P.state.volume,
      muted: P.state.muted,
      shuffle: P.state.shuffle,
      repeat: P.state.repeat,
      engine: P.state.engine,
      format: P.state.format,
      fileFormat: (P.resolveTrackPath(P.state.current).match(/\.([^.]+)$/) || [])[1] || null,
      formats: P.trackFormats(P.state.current),
      queue: P.getQueue(),
      programLocked: P.programLocked,
    };
  }

  // The radio owns playback while this is on: the listener can pause and set
  // volume, but cannot pick, skip, scrub, or queue another track.
  function setProgramLock(enabled) {
    const next = !!enabled;
    if (P.programLocked === next) return;
    P.programLocked = next;
    P.syncProgramLockUi();
    if (P.programLocked) {
      P.closeQueue();
      P.closeSettings();
    }
    P.notify("programlock");
  }

  function seekProgram(seconds) {
    P.setTime(seconds, true);
  }

  function attemptPlay() {
    if (P.state.engine === "howler" && P.howl) {
      try { P.howl.play(); return; } catch {}
    }
    if (P.state.engine === "amplitude" && window.Amplitude) {
      try { window.Amplitude.play(); return; } catch {}
    }
    if (P.state.engine === "aplayer" && P.aplayer) {
      try { P.aplayer.play(); return; } catch {}
    }
    if (P.state.engine === "jplayer" && P.jplayerHost && window.jQuery) {
      try { window.jQuery(P.$("labJPlayerMedia")).jPlayer("play"); return; } catch {}
    }
    let result;
    if (P.state.engine === "mediaelement" && P.mediaElementWrapper) {
      try { result = P.mediaElementWrapper.play(); } catch {}
    }
    if (!result) result = P.audio.play();
    if (result && typeof result.catch === "function") result.catch(() => {});
  }

  function pauseAudio() {
    // A user-initiated pause must silence the fading copy of the previous
    // track too — otherwise it would keep playing until its timer runs out.
    P.stopFades();
    if (P.state.engine === "howler" && P.howl) {
      try { P.howl.pause(); return; } catch {}
    }
    if (P.state.engine === "amplitude" && window.Amplitude) {
      try { window.Amplitude.pause(); return; } catch {}
    }
    if (P.state.engine === "aplayer" && P.aplayer) {
      try { P.aplayer.pause(); return; } catch {}
    }
    if (P.state.engine === "jplayer" && P.jplayerHost && window.jQuery) {
      try { window.jQuery(P.$("labJPlayerMedia")).jPlayer("pause"); return; } catch {}
    }
    if (P.state.engine === "mediaelement" && P.mediaElementWrapper) {
      try { P.mediaElementWrapper.pause(); return; } catch {}
    }
    P.audio.pause();
  }

  function loadCurrent(options = {}) {
    if (!P.state.current) return Promise.resolve(false);
    const track = P.state.current;
    const token = ++P.loadToken;
    const start = Number(options.startTime) || 0;
    const needsRender = P.anyFxEnabled() && !P.isTrackRendered(track);

    const apply = () => {
      if (token !== P.loadToken || P.state.current !== track) return false;
      // An explicit saved position always wins. A fresh start asks the detector
      // for the real end of the initial silence instead of jumping a fixed 12s.
      P.pendingStart = start;
      P.pendingAutoplay = options.autoplay !== false;
      // Use the saved volume, not audio.volume: a previous anti-click ramp may
      // still be in progress and would otherwise become the new ramp's target.
      const incomingTarget = !P.state.muted && !P.audio.muted
        ? Math.max(0, Math.min(1, P.state.volume))
        : 0;
      const fadeInEnabled = P.state.crossfade && P.state.fadeInEnabled && options.fadeIn !== false;
      const fadeInMs = fadeInEnabled ? (Number(options.fadeInMs ?? P.state.fadeInMs) || 0) : 0;

      // Mute main gain before src/load swap to prevent click/pop on the shared
      // element. runIncomingFade will ramp it back up.
      const preGain = P.ensureMainGain();
      if (preGain) {
        try {
          const t = preGain.context.currentTime;
          preGain.gain.cancelScheduledValues(t);
          preGain.gain.setValueAtTime(0.0001, t);
        } catch {}
      }

      const url = P.playableUrl(track);
      // A baked blob already contains the effects; the live preview must be
      // bypassed, but the original file still needs it while a render is due.
      P.syncLiveFx();
      P.destroyWaveforms();
      if (!start && P.state.skipIntro) P.prepareIntro(url);
      else {
        P.introToken++;
        P.introUserSeeked = false;
      }
      P.loadEngine(url, P.pendingStart, P.pendingAutoplay);
      P.applyPlaybackRate();
      // Warm the next file while the current one starts, so switching tracks
      // doesn't feel like waiting for a fresh network request.
      P.schedulePreload();
      if (incomingTarget > 0) {
        P.runIncomingFade(incomingTarget, fadeInMs);
      } else {
        // Ensure gain is not stuck low from a previous fade.
        if (preGain) {
          try { const t = preGain.context.currentTime; preGain.gain.cancelScheduledValues(t); preGain.gain.setValueAtTime(1, t); } catch {}
        } else {
          const g = P.ensureMainGain();
          if (g) { try { const t = g.context.currentTime; g.gain.cancelScheduledValues(t); g.gain.setValueAtTime(1, t); } catch {} }
        }
      }
      return true;
    };

    if (!needsRender) return Promise.resolve(apply());
    // The first switch to an unbaked track waits for its one-time render. All
    // later switches reuse the cached blob with no delay.
    P.setLoading(true, 10);
    return P.ensureRenderedTrack(track).then((baked) => {
      P.setFxRendering(false, !baked);
      return apply();
    }, () => {
      P.setFxRendering(false, true);
      return apply();
    });
  }

  function renderMetadata() {
    if (!P.state.current) return;
    const title = P.state.current.title || "";
    const albumTitle = P.state.context?.title || "";
    // Size the text block to the visible name length so the player has as
    // little empty space as possible next to the centred controls, while still
    // giving long album names room before truncating.
    const textEl = P.$("playerTitle").parentElement;
    if (textEl) {
      const chars = Math.max(title.length, albumTitle.length);
      textEl.style.setProperty("--title-chars", String(Math.min(72, Math.max(10, chars))));
    }
    P.$("playerTitle").textContent = title;
    P.$("playerAlbum").textContent = albumTitle;

    const image = P.$("playerCover");
    const letter = P.$("playerCoverLetter");
    if (P.state.current.cover) {
      image.src = P.assetUrl(P.state.current.cover);
      image.hidden = false;
      letter.hidden = true;
    } else {
      image.removeAttribute("src");
      image.hidden = true;
      letter.hidden = false;
      letter.textContent = (P.state.context?.title || "♪").replace(/^!/, "").charAt(0);
    }

    if ("mediaSession" in navigator && window.MediaMetadata) {
      try {
        navigator.mediaSession.metadata = new MediaMetadata({
          title: P.state.current.title || "",
          artist: "zqwy",
          album: P.state.context?.title || "",
          artwork: P.state.current.cover ? [{ src: P.assetUrl(P.state.current.cover), sizes: "512x512" }] : [],
        });
      } catch {}
    }
    P.updateMediaSessionState();
  }

  function updateMediaSessionState() {
    if (!("mediaSession" in navigator)) return;
    try { navigator.mediaSession.playbackState = P.audio.paused ? "paused" : "playing"; } catch {}
  }

  function playTrack(album, index, options = {}) {
    if (P.programLocked && !options.fromProgram) return;
    if (!album || !album.tracks || !album.tracks[index]) return;
    const track = album.tracks[index];
    const commit = () => {
      P.state.context = {
        albumId: album.id,
        title: album.title,
        cover: album.cover || null,
        tracks: album.tracks.map((item) => ({ title: item.title, path: item.path, formats: item.formats })),
      };
      P.state.current = {
        albumId: album.id,
        index,
        title: track.title,
        path: track.path,
        formats: track.formats,
        cover: album.cover || null,
      };
      P.state.time = 0;
      P.showBar();
      P.renderMetadata();
      P.loadCurrent({
        autoplay: options.autoplay !== false,
        startTime: options.startTime || 0,
        fadeIn: options.autoplay !== false,
      });
      P.saveState();
      P.notify("track");
    };
    if (options.autoplay !== false) P.beginCrossfade(track, commit);
    else commit();
  }

  function setContext(album) {
    if (P.programLocked || !album) return;
    const sameAlbum = P.state.context && P.state.context.albumId === album.id;
    if (!sameAlbum) {
      P.state.context = {
        albumId: album.id,
        title: album.title,
        cover: album.cover || null,
        tracks: album.tracks.map((item) => ({ title: item.title, path: item.path, formats: item.formats })),
      };
      P.saveState();
      // A new album invalidates the old album's "up next" file. Wait for an
      // explicit playTrack() before warming anything from the new context.
      P.cancelPreload();
    }
  }

  function selectByIndex(index, autoplay = true) {
    if (P.programLocked) return;
    const tracks = P.state.context?.tracks;
    if (!tracks || !tracks.length) return;
    const wrapped = ((index % tracks.length) + tracks.length) % tracks.length;
    const item = tracks[wrapped];
    const commit = () => {
      P.state.current = {
        albumId: P.state.context.albumId,
        index: wrapped,
        title: item.title,
        path: item.path,
        formats: item.formats,
        cover: P.state.context.cover,
      };
      P.state.time = 0;
      P.showBar();
      P.renderMetadata();
      P.loadCurrent({ autoplay, startTime: 0, fadeIn: autoplay });
      P.saveState();
      P.notify("track");
    };
    if (autoplay) P.beginCrossfade(item, commit);
    else commit();
  }

  function next(manual = false) {
    if (P.programLocked) return; // the radio advances strictly by the clock
    // An explicit queue always wins over the album's own order: these are the
    // tracks the visitor deliberately marked as "up next".
    if (P.state.queue.length) { P.playQueued(0); return; }
    if (!P.state.current || !P.state.context?.tracks?.length) return;
    const length = P.state.context.tracks.length;
    if (P.state.shuffle && length > 1) {
      const target = P.pickShuffleIndex();
      P.shufflePick = null; // the preloaded pick has been consumed
      P.selectByIndex(target ?? P.state.current.index + 1);
      return;
    }
    if (P.state.current.index + 1 < length) P.selectByIndex(P.state.current.index + 1);
    else if (manual || P.state.repeat === "all" || P.state.autoNext) P.selectByIndex(0);
    else P.pauseAudio();
  }

  function previous() {
    if (P.programLocked || !P.state.current) return;
    if (P.audio.currentTime > 3) { P.setTime(0); return; }
    P.selectByIndex(P.state.current.index - 1);
  }

  function handleEnded() {
    if (P.programLocked) return; // radio tick selects the next scheduled file
    if (P.state.repeat === "one") { P.setTime(0); P.attemptPlay(); return; }
    P.next(false);
  }

  function setTime(seconds, fromProgram = false) {
    if (P.programLocked && !fromProgram) return;
    if (!Number.isFinite(seconds)) return;
    const duration = Number.isFinite(P.audio.duration) ? P.audio.duration : seconds;
    P.audio.currentTime = Math.max(0, Math.min(seconds, duration));
  }

  function toggle() {
    if (!P.state.current) return;
    if (P.audio.paused) P.attemptPlay();
    else P.pauseAudio();
  }

  function stop() {
    // Closing the player must not let a pending crossfade commit a new track.
    P.stopFades({ commit: false });
    P.incomingFadeToken++;
    P.incomingFadeActive = 0;
    if (P.mainGainNode) {
      try {
        const t = P.audioContext.currentTime;
        P.mainGainNode.gain.cancelScheduledValues(t);
        P.mainGainNode.gain.setValueAtTime(1, t);
      } catch { P.mainGainNode.gain.value = 1; }
    }
    P.pauseAudio();
    P.audio.removeAttribute("src");
    P.audio.load();
    P.cancelPreload();
    P.setLoading(false);
    P.destroyWaveforms();
    P.setWaveMode(false);
    P.closeSettings();
    P.state.current = null;
    P.state.time = 0;
    P.hideBar();
    P.$("playerTitle").textContent = P.pt("nothingPlaying");
    P.$("playerAlbum").textContent = "";
    P.updateTime();
    P.saveState();
    P.notify("stop");
  }
  Object.assign(P, { assetUrl, sourceUrl, playableUrl, basePrefix, cssVar, formatTime, trackFormats, sourceTrackPath, renderKey, renderedEntry, isTrackRendered, resolveTrackPath, setFormat, notify, getState, setProgramLock, seekProgram, attemptPlay, pauseAudio, loadCurrent, renderMetadata, updateMediaSessionState, playTrack, setContext, selectByIndex, next, previous, handleEnded, setTime, toggle, stop });
}
